F="Painted 3D-rendered scene with an American comic book finish: physically modelled materials, one warm key light, soft depth of field, bold black ink contour lines, Ben-Day halftone dots only inside the shadows. Palette: deep black, gold, green and red. No text, no letters, no numbers, no logos, no signs."
j(){ python3 -c 'import json,sys;print(json.dumps({"prompt":sys.argv[1],"aspect_ratio":sys.argv[2],"resolution":"1K","quality":"medium","output_format":"png","num_outputs":1}))' "$1" "$2"; }
python3 hd.py vault-full gpt-image-2 "$(j "Inside a bank vault seen straight on from the open round door: a riveted steel back wall, a polished round brass plaque mounted high in the middle of the wall, blank and empty like a gauge face with nothing on it, a stone floor, and a great mound of gold coins rising from the floor to about two thirds of the wall height, coins glinting, a few loose coins in front. No people. $F" 9:16)" > log-vault-full.txt 2>&1 &
python3 hd.py exch-day gpt-image-2 "$(j "A grand 1920s stock exchange trading floor seen straight on: high in the centre a huge brass-framed wall clock with a completely blank cream face, no numerals and no hands; on the left wall a large polished brass bell on an iron bracket; a gallery balcony, empty wooden trading posts, tall windows with bright morning light, a few early traders in waistcoats as small figures. $F" 9:16)" > log-exch-day.txt 2>&1 &
python3 hd.py exch-day-w gpt-image-2 "$(j "A grand 1920s stock exchange trading floor seen straight on, wide: high in the centre a huge brass-framed wall clock with a completely blank cream face, no numerals and no hands; on the left wall a large polished brass bell on an iron bracket; a gallery balcony, wooden trading posts, tall windows with bright morning light, a few early traders in waistcoats as small figures. $F" 16:9)" > log-exch-day-w.txt 2>&1 &
python3 hd.py bell-black gpt-image-2 "$(j "One large polished brass exchange bell hanging from a short black iron bracket, the clapper visible, isolated on a pure flat black background, warm key light from the upper left. Nothing else. $F" 1:1)" > log-bell.txt 2>&1 &
python3 hd.py window gpt-image-2 "$(j "A brass betting window at an old stock exchange seen straight on: a dark wooden counter under an ornate brass grille, on the counter a blank cream betting slip and two rubber stamps standing beside it, one with a green wooden handle and one with a red wooden handle; behind the grille a cork pinboard with four blank cream slips pinned in a row; a green banker's lamp; nobody there. $F" 9:16)" > log-window.txt 2>&1 &
python3 hd.py radio-black gpt-image-2 "$(j "A 1930s wooden cathedral radio with a round amber dial window and one brass knob, isolated on a pure flat black background, warm key light. Nothing else. $F" 1:1)" > log-radio.txt 2>&1 &
